import type { VariantDef } from '../inventory/types';

export type QuirkType = 'Physical' | 'Behavioral' | 'Vocal';

/**
 * A minor behavioral oddity or habitual tic that makes a character
 * memorable. Quirks are purely narrative and do not impose mechanical
 * penalties, but add personality depth to the character sheet.
 */
export interface Quirk {
  id: string;
  name: string;
  type: QuirkType;
  description: string;
  variants: VariantDef[];
  mechanicalEffect?: string;
  weight: number;
}

